{
  "name": "telegram-command-bridge",
  "version": "1.0.0",
  "description": "Message your Telegram bot and a headless Claude Code agent runs on your machine with real tools, replying with the result.",
  "license": "MIT",
  "type": "commonjs",
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "grammy": "^1"
  },
  "scripts": {
    "setup": "node tg-setup.cjs",
    "start": "node tg-watch.cjs",
    "selftest": "node tg-selftest.cjs"
  }
}

#!/usr/bin/env node
'use strict';

/**
 * tg-setup.cjs — one-shot Telegram channel link for the operator.
 * Paste a BotFather token; auto-discovers chat id; merges into .env.
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');
const { Bot } = require('grammy');

const paths = null;

const ROOT = __dirname;
const ENV_PATH = path.join(ROOT, '.env');
const CHANNEL_PATH = paths && paths.memory
  ? path.join(paths.memory, 'telegram-channel.json')
  : path.join(ROOT, 'memory', 'telegram-channel.json');
const SOFT_FAIL = paths && paths.memory
  ? path.join(paths.memory, 'soft-failures.jsonl')
  : path.join(ROOT, 'memory', 'soft-failures.jsonl');

const TOKEN_RE = /^\d{6,12}:[A-Za-z0-9_-]{30,}$/;
// 180s was a race against a human finding the right chat -- it timed out on the operator twice. The window
// is a convenience, not a correctness bound: nothing is at risk while we wait for one message.
const WAIT_MS = Number(process.env.TG_SETUP_WAIT_MS || 180_000);
const POLL_MS = 1500;

function redactToken(token) {
  if (!token || typeof token !== 'string') return '(none)';
  const i = token.indexOf(':');
  if (i < 0) return '***';
  return `${token.slice(0, Math.min(i, 9))}:AA…`;
}

function softFail(where, err, extra) {
  try {
    fs.mkdirSync(path.dirname(SOFT_FAIL), { recursive: true });
    const row = {
      ts: new Date().toISOString(),
      where,
      error: err && err.message ? err.message : String(err),
      ...(extra || {}),
    };
    fs.appendFileSync(SOFT_FAIL, JSON.stringify(row) + '\n', 'utf8');
  } catch (e) {
    console.error('[tg-setup] soft-fail write failed:', e.message);
  }
}

function atomicWrite(filePath, contents) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const tmp = `${filePath}.${process.pid}.${Date.now()}.tmp`;
  fs.writeFileSync(tmp, contents, 'utf8');
  fs.renameSync(tmp, filePath);
}

function readJsonSafe(filePath) {
  try {
    if (!fs.existsSync(filePath)) return null;
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    softFail('tg-setup/readJson', err, { file: filePath });
    return null;
  }
}

function mergeEnv(envPath, updates) {
  let existing = '';
  if (fs.existsSync(envPath)) {
    existing = fs.readFileSync(envPath, 'utf8');
  }
  const lines = existing.length ? existing.split(/\r?\n/) : [];
  const keys = Object.keys(updates);
  const seen = new Set();
  const out = [];

  for (const line of lines) {
    const m = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
    if (m && keys.includes(m[1])) {
      out.push(`${m[1]}=${updates[m[1]]}`);
      seen.add(m[1]);
    } else {
      out.push(line);
    }
  }

  while (out.length && out[out.length - 1] === '') out.pop();
  for (const k of keys) {
    if (!seen.has(k)) out.push(`${k}=${updates[k]}`);
  }
  out.push('');
  atomicWrite(envPath, out.join('\n'));
}

function loadEnvFile(envPath) {
  if (!fs.existsSync(envPath)) return {};
  const map = {};
  const text = fs.readFileSync(envPath, 'utf8');
  for (const line of text.split(/\r?\n/)) {
    if (!line || line.trim().startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq < 0) continue;
    const key = line.slice(0, eq).trim();
    let val = line.slice(eq + 1);
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }
    map[key] = val;
  }
  return map;
}

function printBotFatherSteps() {
  console.log('');
  console.log('══════════════════════════════════════════════════');
  console.log('  Telegram Command Channel — one-time setup');
  console.log('══════════════════════════════════════════════════');
  console.log('');
  console.log('  1. Open Telegram and search for @BotFather');
  console.log('  2. Send /newbot and follow the prompts');
  console.log('  3. Copy the token BotFather gives you and paste it here');
  console.log('');
}

// EOF-safe: rl.question's callback never fires on EOF, so the old version's Promise never resolved —
// readline closed stdin, the event loop drained, and node exited 0 having configured NOTHING (a silent
// success on failure; the `if (!TOKEN_RE.test(token))` exit-1 below was simply never reached).
// Always resolve: no TTY -> '' immediately; 'close' -> ''; `settled` guards the double-resolve race.
function promptToken() {
  return new Promise((resolve) => {
    if (!process.stdin.isTTY) {
      resolve('');
      return;
    }
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
    });
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve((value || '').trim());
    };
    rl.on('close', () => finish(''));
    rl.question('Paste your BotFather token: ', (answer) => {
      finish(answer);
      rl.close();
    });
  });
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function discoverChat(bot, botUsername) {
  console.log('');
  console.log(
    `Now open Telegram, find @${botUsername}, and send it any message (e.g. hi). Waiting…`
  );
  console.log(`(timeout in ${WAIT_MS / 1000}s)`);
  console.log('');

  const deadline = Date.now() + WAIT_MS;
  let offset = 0;

  try {
    const stale = await bot.api.getUpdates({ timeout: 0, offset: -1 });
    if (Array.isArray(stale) && stale.length > 0) {
      offset = stale[stale.length - 1].update_id + 1;
    }
  } catch (err) {
    softFail('tg-setup/drainUpdates', err);
    console.error('Warning: could not drain prior updates:', err.message);
  }

  while (Date.now() < deadline) {
    let updates;
    try {
      updates = await bot.api.getUpdates({
        offset,
        timeout: 25,
        allowed_updates: ['message'],
      });
    } catch (err) {
      softFail('tg-setup/getUpdates', err);
      console.error('getUpdates error (retrying):', err.message);
      await sleep(POLL_MS);
      continue;
    }

    if (!Array.isArray(updates) || updates.length === 0) {
      await sleep(200);
      continue;
    }

    for (const upd of updates) {
      offset = upd.update_id + 1;
      const msg = upd.message;
      if (!msg || !msg.chat) continue;
      const chatId = msg.chat.id;
      const fromUser =
        (msg.from && (msg.from.username || msg.from.first_name)) || 'unknown';
      return { chatId, fromUser, msg };
    }
  }

  return null;
}

async function main() {
  const relink = process.argv.includes('--relink');
  const envMap = loadEnvFile(ENV_PATH);
  const existing = readJsonSafe(CHANNEL_PATH);
  const existingToken =
    process.env.TELEGRAM_BOT_TOKEN || envMap.TELEGRAM_BOT_TOKEN || '';
  const existingChat =
    process.env.TELEGRAM_CHAT_ID || envMap.TELEGRAM_CHAT_ID || '';

  if (
    !relink &&
    existing &&
    existing.chat_id &&
    existingToken &&
    TOKEN_RE.test(existingToken) &&
    existingChat
  ) {
    console.log('');
    console.log('Telegram channel already linked:');
    console.log(`  bot:      @${existing.bot_username || '?'}`);
    console.log(`  chat_id: ${existing.chat_id}`);
    console.log(`  user:    @${existing.username || '?'}`);
    console.log(`  linked:  ${existing.linked_at || '?'}`);
    console.log('');
    console.log('Re-run with --relink to redo discovery.');
    console.log(`  node tg-setup.cjs --relink`);
    process.exit(0);
  }

  printBotFatherSteps();

  const argvTok = process.argv.slice(2).find((a) => a !== '--relink' && TOKEN_RE.test(a));
  let token =
    argvTok ||
    process.env.TELEGRAM_BOT_TOKEN ||
    envMap.TELEGRAM_BOT_TOKEN ||
    '';

  if (!TOKEN_RE.test(token)) {
    token = await promptToken();
  }

  if (!TOKEN_RE.test(token)) {
    console.error('');
    console.error('INVALID TOKEN SHAPE.');
    console.error(
      'BotFather gave you a token like 123456789:AA... — paste the whole thing'
    );
    console.error(`Got: ${redactToken(token)}`);
    process.exit(1);
  }

  const bot = new Bot(token);
  let me;
  try {
    me = await bot.api.getMe();
  } catch (err) {
    softFail('tg-setup/getMe', err, { token: redactToken(token) });
    console.error('');
    console.error('TOKEN REJECTED by Telegram.');
    console.error(
      'BotFather gave you a token like 123456789:AA... — paste the whole thing'
    );
    console.error(`Tried: ${redactToken(token)}`);
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  const botUsername = me.username || me.first_name || 'bot';
  console.log(`✓ Token OK — bot is @${botUsername}`);

  const found = await discoverChat(bot, botUsername);
  if (!found) {
    console.error('');
    console.error(
      `Timed out after ${Math.round(WAIT_MS / 1000)}s — no message received from you.`
    );
    console.error(
      `Open Telegram, message @${botUsername}, then re-run:`
    );
    console.error('  node tg-setup.cjs --relink');
    process.exit(2);
  }

  const { chatId, fromUser } = found;

  try {
    await bot.api.sendMessage(
      chatId,
      '✅ Bridge connected. This chat is now your command channel.'
    );
  } catch (err) {
    softFail('tg-setup/confirmMessage', err, { chatId });
    console.error('Warning: could not send confirm message:', err.message);
  }

  mergeEnv(ENV_PATH, {
    TELEGRAM_BOT_TOKEN: token,
    TELEGRAM_CHAT_ID: String(chatId),
  });

  const channel = {
    chat_id: chatId,
    username: fromUser,
    bot_username: botUsername,
    linked_at: new Date().toISOString(),
  };
  atomicWrite(CHANNEL_PATH, JSON.stringify(channel, null, 2) + '\n');

  console.log('');
  console.log('Connected.');
  console.log(`  bot:      @${botUsername}`);
  console.log(`  chat_id: ${chatId}`);
  console.log(`  user:    @${fromUser}`);
  console.log(`  wrote:   .env (TELEGRAM_BOT_TOKEN + TELEGRAM_CHAT_ID)`);
  console.log(`  wrote:   memory/telegram-channel.json`);
  console.log('');
  console.log('Next: start the daemon');
  console.log('  node tg-watch.cjs');
  console.log('');
}

main().catch((err) => {
  softFail('tg-setup/main', err);
  console.error('FATAL:', err && err.stack ? err.stack : err);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';

/**
 * Live Telegram agent lane: read inbox → advance cursor → run claude → outbox reply.
 * A reply must be the result of actual work (or an honest failure) — never a fake receipt.
 */

const fs = require('fs');
const path = require('path');
const { spawn, spawnSync } = require('child_process');

const AGENT_WALL_MS = Number(process.env.TG_AGENT_WALL_MS || 900000);
const ACK_AFTER_MS = Number(process.env.TG_AGENT_ACK_AFTER_MS || 10000);
const CHUNK_MAX = 3900;
const MAX_MSGS_PER_RUN = 20;
const MAX_ROUNDS = (() => {
  const n = Number(process.env.TG_AGENT_MAX_ROUNDS || 5);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 5;
})();

// FULL ORCHESTRATION (the operator, 7/15): every inbound message on this bridge IS the operator — his named gates
// (pushes, deploys, CRM, outbound email) exist to gate the AGENT acting alone, not the operator commanding it.
// Default deny list is therefore EMPTY. Deny rules still bind under skip-permissions (verified) — add
// patterns via TG_AGENT_EXTRA_DENY if a structural gate is ever wanted again.
// Safe default: the agent runs with permissions bypassed (no human approves each tool call), so the
// highest-blast-radius operations are denied out of the box. Deny rules bind even under skip-permissions.
// Full orchestration (empty this list) is a deliberate choice — do it only on a machine you fully control.
// Extend or override via TG_AGENT_EXTRA_DENY (comma-separated glob patterns).
const DISALLOWED_TOOLS = [
  'Bash(git push*)',
  'Bash(rm -rf*)',
  'Bash(rm -fr*)',
  'Bash(sudo*)',
  'Bash(shutdown*)',
  'Bash(reboot*)',
];
if (process.env.TG_AGENT_EXTRA_DENY) {
  for (const p of String(process.env.TG_AGENT_EXTRA_DENY).split(',')) {
    const t = p.trim();
    if (t) DISALLOWED_TOOLS.push(t);
  }
}

const paths = null;
const ROOT = __dirname;
const MEMORY = path.join(ROOT, 'memory');

const INBOX = path.join(MEMORY, 'inbox.jsonl');
const OUTBOX = path.join(MEMORY, 'outbox.jsonl');
const CURSOR = path.join(MEMORY, 'tg-agent-cursor.json');
const LOCK = path.join(MEMORY, 'tg-agent.lock');
const LOG = path.join(MEMORY, 'tg-agent-log.jsonl');
const SOFT_FAIL = path.join(MEMORY, 'soft-failures.jsonl');

const APPEND_SYSTEM_PROMPT = [
  'You are a headless assistant answering the operator over Telegram from their phone.',
  'You have full computer-use authority on this machine.',
  'You must DO the work with your tools, not describe it.',
  'Reply in plain text only — no markdown tables or headers (phones render them badly).',
  'Be concise.',
  'If you cannot do something, say exactly why.',
  'Operations named in DISALLOWED_TOOLS are structurally denied; if asked for one, say it must be run by the operator directly and do not attempt it.',
].join(' ');

function softFail(script, err) {
  try {
    ensureMemory();
    const row = {
      ts: new Date().toISOString(),
      script: String(script),
      error: String(err && err.stack ? err.stack : err && err.message ? err.message : err).slice(0, 2000),
    };
    fs.appendFileSync(SOFT_FAIL, JSON.stringify(row) + '\n', 'utf8');
  } catch {
    // softFail must never throw
  }
}

function ensureMemory() {
  fs.mkdirSync(MEMORY, { recursive: true });
}

function writeJsonAtomic(file, obj) {
  ensureMemory();
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2), 'utf8');
  try {
    fs.renameSync(tmp, file);
  } catch {
    // Windows cannot rename over an existing file
    try {
      fs.unlinkSync(file);
    } catch (e) {
      try {
        fs.unlinkSync(tmp);
      } catch {
        /* ignore */
      }
      throw e;
    }
    fs.renameSync(tmp, file);
  }
}

function readJson(file, fallback) {
  try {
    if (!fs.existsSync(file)) return fallback;
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (e) {
    softFail('tg-agent-readJson', e);
    return fallback;
  }
}

function isPidAlive(pid) {
  if (pid == null || typeof pid !== 'number' || !Number.isFinite(pid) || pid <= 0) {
    return false;
  }
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

function acquireLock() {
  ensureMemory();
  const payload = JSON.stringify({ pid: process.pid, started_at: new Date().toISOString() });
  // Atomic exclusive create ('wx') — NOT check-then-write. Two agents spawned within the debounce window
  // must not both pass an existsSync check and both run claude under --dangerously-skip-permissions.
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      fs.writeFileSync(LOCK, payload, { flag: 'wx' });
      return true;
    } catch (e) {
      if (e.code !== 'EEXIST') { softFail('tg-agent-lock-write', e); return false; }
      let holder = null;
      try { holder = JSON.parse(fs.readFileSync(LOCK, 'utf8')); } catch { /* corrupt lock */ }
      if (holder && isPidAlive(holder.pid)) return false; // a live agent holds it
      try { fs.unlinkSync(LOCK); } catch (e2) { softFail('tg-agent-lock-steal', e2); return false; }
      // dead-holder lock removed; loop retries the exclusive create once
    }
  }
  return false;
}

function releaseLock() {
  try {
    if (!fs.existsSync(LOCK)) return;
    let lock;
    try {
      lock = JSON.parse(fs.readFileSync(LOCK, 'utf8'));
    } catch {
      return;
    }
    if (lock.pid === process.pid) {
      fs.unlinkSync(LOCK);
    }
  } catch (e) {
    softFail('tg-agent-lock-release', e);
  }
}

function tsGreater(a, b) {
  if (b == null || b === '') return true;
  if (a == null || a === '') return false;
  if (typeof a === 'number' && typeof b === 'number') return a > b;
  const na = Number(a);
  const nb = Number(b);
  if (Number.isFinite(na) && Number.isFinite(nb) && String(a).trim() !== '' && String(b).trim() !== '') {
    // numeric-looking timestamps (epoch ms / seconds)
    if (!/^\d+(\.\d+)?$/.test(String(a).trim()) || !/^\d+(\.\d+)?$/.test(String(b).trim())) {
      return String(a) > String(b);
    }
    return na > nb;
  }
  return String(a) > String(b);
}

function readInboxRows() {
  if (!fs.existsSync(INBOX)) return [];
  let raw;
  try {
    raw = fs.readFileSync(INBOX, 'utf8');
  } catch (e) {
    softFail('tg-agent-inbox-read', e);
    throw e;
  }
  const rows = [];
  for (const line of raw.split(/\r?\n/)) {
    if (!line.trim()) continue;
    try {
      rows.push(JSON.parse(line));
    } catch (e) {
      softFail('tg-agent-inbox-parse', e.message || e);
    }
  }
  return rows;
}

const MEDIA_TYPES = ['photo', 'document', 'voice', 'audio', 'video', 'video_note', 'sticker'];
function isMediaRow(row) {
  return !!row.media_path || MEDIA_TYPES.includes(row.type);
}

function selectPending(lastTs) {
  const pending = [];
  for (const row of readInboxRows()) {
    if (!row || typeof row !== 'object') continue;
    if (row.selftest === true) continue;
    if (row.from === 'tg-selftest') continue;
    // Only this bridge's own lane. other lanes rows (written unstamped by the daemon) must not get a
    // full-orchestration run answered on Telegram. The daemon stamps every telegram inbox write.
    if (row.channel !== 'telegram') continue;
    const hasText = row.text != null && String(row.text).trim() !== '';
    if (!hasText) {
      // A media message is real pending work — synthesize prompt text so the run can act on the file,
      // instead of the old `text`-required check silently dropping every photo/voice/document forever.
      if (isMediaRow(row)) {
        row.text = `[${row.type || 'media'}]${row.caption ? ' ' + row.caption : ''}${row.media_path ? ' (file: ' + row.media_path + ')' : ''}`;
      } else {
        continue;
      }
    }
    if (!tsGreater(row.ts, lastTs)) continue;
    pending.push(row);
  }
  pending.sort((a, b) => {
    if (a.ts === b.ts) return 0;
    return tsGreater(a.ts, b.ts) ? 1 : -1;
  });
  return pending;
}

function buildPrompt(rows, skippedOlder) {
  let body;
  if (rows.length === 1) {
    body = String(rows[0].text);
  } else {
    body = rows
      .map((r, i) => {
        const who = r.from != null ? String(r.from) : 'operator';
        const when = r.ts != null ? String(r.ts) : '';
        return `Message ${i + 1}/${rows.length}${when ? ` (${when})` : ''} from ${who}:\n${String(r.text)}`;
      })
      .join('\n\n---\n\n');
  }
  if (skippedOlder > 0) {
    return (
      `(Note: ${skippedOlder} older pending message(s) were skipped; only the newest ${rows.length} are included.)\n\n` +
      body
    );
  }
  return body;
}

function chunkText(text, max) {
  const s = String(text);
  if (!s) return [];
  if (s.length <= max) return [s];

  const chunks = [];
  const lines = s.split('\n');
  let buf = '';

  const flush = () => {
    if (buf) {
      chunks.push(buf);
      buf = '';
    }
  };

  const hardSplit = (line) => {
    for (let i = 0; i < line.length; i += max) {
      chunks.push(line.slice(i, i + max));
    }
  };

  for (const line of lines) {
    if (line.length > max) {
      flush();
      hardSplit(line);
      continue;
    }
    const next = buf ? `${buf}\n${line}` : line;
    if (next.length > max) {
      flush();
      buf = line;
    } else {
      buf = next;
    }
  }
  flush();
  return chunks;
}

function makeOutboxId(seq) {
  return `tg-${Date.now()}-${process.pid}-${seq}-${Math.random().toString(36).slice(2, 10)}`;
}

function enqueueReply(text) {
  ensureMemory();
  const chunks = chunkText(text, CHUNK_MAX);
  if (!chunks.length) {
    chunks.push('(empty reply)');
  }
  let seq = 0;
  for (const chunk of chunks) {
    const row = {
      id: makeOutboxId(seq++),
      text: chunk,
      ts: new Date().toISOString(),
      channel: 'telegram',
    };
    fs.appendFileSync(OUTBOX, JSON.stringify(row) + '\n', 'utf8');
  }
  return chunks.reduce((n, c) => n + c.length, 0);
}

function audit(entry) {
  try {
    ensureMemory();
    fs.appendFileSync(LOG, JSON.stringify(entry) + '\n', 'utf8');
  } catch {
    // audit must never throw
  }
}

function killTree(child) {
  const pid = child && child.pid;
  // Already reaped: killing now could /T /F an unrelated process that reused this PID.
  if (!child || child.exitCode !== null || child.signalCode !== null) return;
  // taskkill /T FIRST — it kills the whole tree (grandchildren included). Doing child.kill() first would
  // orphan the grandchildren before taskkill can reach them.
  if (process.platform === 'win32' && pid) {
    try {
      spawnSync('taskkill', ['/pid', String(pid), '/T', '/F'], {
        windowsHide: true,
        stdio: 'ignore',
      });
    } catch (e) {
      softFail('tg-agent-taskkill', e);
    }
  }
  try {
    if (!child.killed) child.kill();
  } catch (e) {
    softFail('tg-agent-kill', e);
  }
}

// Absolute path required: spawn(name) without shell does not apply PATHEXT on Windows (EINVAL).
// On win32 the official installer drops claude.exe, but `npm i -g @anthropic-ai/claude-code` drops a
// claude.cmd batch shim (no .exe). Search .exe FIRST (native, spawns cleanly), then the shims — else an
// npm-only install reads as "not found". runClaude() handles the .cmd/.bat spawn path (Node can't spawn
// a batch file directly — EINVAL, CVE-2024-27980).
function claudeBinNames() {
  return process.platform === 'win32'
    ? ['claude.exe', 'claude.cmd', 'claude.bat', 'claude']
    : ['claude'];
}

function resolveClaudeBin() {
  const override = process.env.CLAUDE_BIN;
  if (override && fs.existsSync(override)) {
    return override;
  }
  const pathEnv = process.env.PATH || '';
  for (const dir of pathEnv.split(path.delimiter)) {
    if (!dir) continue;
    for (const binName of claudeBinNames()) {
      const candidate = path.join(dir, binName);
      if (fs.existsSync(candidate)) {
        return candidate;
      }
    }
  }
  return null;
}

function describeClaudeSearch() {
  const parts = [];
  if (process.env.CLAUDE_BIN) {
    parts.push(`CLAUDE_BIN=${process.env.CLAUDE_BIN}`);
  }
  const binName = process.platform === 'win32' ? 'claude.exe' : 'claude';
  const pathEnv = process.env.PATH || '';
  for (const dir of pathEnv.split(path.delimiter)) {
    if (!dir) continue;
    parts.push(path.join(dir, binName));
  }
  return parts.length ? parts.join('; ') : '(no PATH entries and CLAUDE_BIN unset)';
}

const CLAUDE_BIN = resolveClaudeBin();

function formatAckClock(d) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function runClaude(prompt) {
  return new Promise((resolve) => {
    const args = [
      '-p',
      '--dangerously-skip-permissions',
      '--output-format',
      'text',
      '--strict-mcp-config',
      // A bare --disallowedTools with no patterns would swallow the next flag as its value
      ...(DISALLOWED_TOOLS.length ? ['--disallowedTools', ...DISALLOWED_TOOLS] : []),
      '--append-system-prompt',
      APPEND_SYSTEM_PROMPT,
    ];

    // Never shell:true — args are concatenated unescaped (DEP0190); prompts contain quotes/newlines/emoji.
    // The user's message goes in via STDIN (below), so ONLY our controlled flags + the single-line
    // APPEND_SYSTEM_PROMPT ride argv — no untrusted data on the command line.
    const cmd = CLAUDE_BIN;
    const started = Date.now();
    const startedAt = new Date(started);
    let stdout = '';
    let stderr = '';
    let settled = false;
    let timedOut = false;
    let acked = false;
    let forceTimer = null;
    let ackTimer = null;

    // Node refuses to spawn a .cmd/.bat directly (EINVAL, CVE-2024-27980). An npm-only Windows install
    // has ONLY claude.cmd, so route batch shims through cmd.exe with verbatim, individually-quoted args
    // — that keeps the multi-word APPEND_SYSTEM_PROMPT a SINGLE argument (shell:true would split it on
    // spaces). Our argv has no ", %, or newlines, so double-quote wrapping is sufficient and safe. The
    // native .exe / bare path is byte-identical to before (zero change for the live bridge).
    const lower = String(cmd).toLowerCase();
    const isBatch =
      process.platform === 'win32' && (lower.endsWith('.cmd') || lower.endsWith('.bat'));
    const baseOpts = {
      cwd: ROOT,
      env: process.env,
      windowsHide: true,
      stdio: ['pipe', 'pipe', 'pipe'],
    };
    let child;
    if (isBatch) {
      const q = (a) => (/[\s"&|<>^()%!]/.test(String(a)) ? `"${String(a).replace(/"/g, '""')}"` : String(a));
      const comspec = process.env.COMSPEC || 'cmd.exe';
      // cmd.exe /s strips ONLY the outer leading+trailing quote of the whole /c operand. So wrap the
      // entire `"bin" args` string in ONE more quote pair: /s peels the outer pair and the inner quotes
      // survive. Passing them as separate argv elements instead lets /s strip the BIN's own quotes and
      // splice a path that has a space (C:\Program Files\…\claude.cmd, or a spaced Windows username),
      // also dropping the final arg's closing quote. (bugbot CRITICAL, 2026-07-15.)
      const line = [q(cmd), ...args.map(q)].join(' ');
      child = spawn(comspec, ['/d', '/s', '/c', `"${line}"`], {
        ...baseOpts,
        windowsVerbatimArguments: true,
      });
    } else {
      child = spawn(cmd, args, baseOpts);
    }

    const finish = (payload) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (ackTimer) clearTimeout(ackTimer);
      if (forceTimer) clearTimeout(forceTimer);
      resolve({ ...payload, acked });
    };

    // Honest progress ack: only when the child is still running after ACK_AFTER_MS — states a fact, never a fake receipt.
    ackTimer = setTimeout(() => {
      if (settled) return;
      acked = true;
      try {
        enqueueReply(
          `⚙️ On it — agent running (started ${formatAckClock(startedAt)}). You'll get the result or an honest failure, nothing silent.`,
        );
      } catch (e) {
        softFail('tg-agent-ack', e);
      }
    }, ACK_AFTER_MS);
    ackTimer.unref();

    const timer = setTimeout(() => {
      timedOut = true;
      killTree(child);
      // If close never arrives after taskkill, still settle so the operator gets a timeout reply
      forceTimer = setTimeout(() => {
        finish({
          stdout,
          stderr,
          exitCode: null,
          signal: null,
          timedOut: true,
          elapsedMs: Date.now() - started,
          spawnError: null,
        });
      }, 8000);
      forceTimer.unref();
    }, AGENT_WALL_MS);
    timer.unref();

    if (child.stdout) {
      child.stdout.setEncoding('utf8');
      child.stdout.on('data', (d) => {
        stdout += d;
      });
    }
    if (child.stderr) {
      child.stderr.setEncoding('utf8');
      child.stderr.on('data', (d) => {
        stderr += d;
      });
    }

    child.on('error', (err) => {
      finish({
        stdout,
        stderr: stderr + (stderr ? '\n' : '') + String(err && err.stack ? err.stack : err),
        exitCode: null,
        timedOut: false,
        elapsedMs: Date.now() - started,
        spawnError: err,
      });
    });

    child.on('close', (code, signal) => {
      finish({
        stdout,
        stderr,
        exitCode: code,
        signal: signal || null,
        timedOut,
        elapsedMs: Date.now() - started,
        spawnError: null,
      });
    });

    try {
      if (!child.stdin) {
        throw new Error('claude stdin unavailable');
      }
      // Async EPIPE (pipe breaks mid-flush) surfaces as a stdin 'error' EVENT, not a throw here — without
      // this listener it is an unhandled error that crashes tg-agent AFTER the cursor advanced (silent drop).
      child.stdin.on('error', (err) => {
        softFail('tg-agent-stdin-async', err);
        killTree(child);
        finish({
          stdout,
          stderr: stderr + (stderr ? '\n' : '') + String(err && err.message ? err.message : err),
          exitCode: null,
          timedOut: false,
          elapsedMs: Date.now() - started,
          spawnError: err,
        });
      });
      child.stdin.write(prompt, 'utf8');
      child.stdin.end();
    } catch (e) {
      softFail('tg-agent-stdin', e);
      killTree(child);
      finish({
        stdout,
        stderr: stderr + (stderr ? '\n' : '') + String(e && e.message ? e.message : e),
        exitCode: null,
        timedOut: false,
        elapsedMs: Date.now() - started,
        spawnError: e,
      });
    }
  });
}

function stderrTail(stderr, n) {
  const s = String(stderr || '');
  if (s.length <= n) return s;
  return s.slice(-n);
}

async function main() {
  ensureMemory();

  // Maintenance switch: when memory/tg-agent.pause exists, no spawned agent runs claude — it exits
  // quietly (no reply). Lets the desktop session own a delicate task without racing phone-spawned agents.
  if (fs.existsSync(path.join(MEMORY, 'tg-agent.pause'))) {
    return;
  }

  if (!acquireLock()) {
    return;
  }

  // Catch-path fallbacks only; each round resets its own working copies below.
  let msgCount = 0;
  let promptChars = 0;
  let replyChars = 0;
  let outcome = 'error';
  let exitCode = null;
  let acked = false;
  let round = 0;
  const holdStartedAt = Date.now();

  try {
    // Missing cursor file = first-run bootstrap (do not replay history). A present file with last_ts:null is different.
    if (!fs.existsSync(CURSOR)) {
      const rows = readInboxRows();
      let newest = null;
      for (const row of rows) {
        if (!row || row.ts == null || row.ts === '') continue;
        if (newest == null || tsGreater(row.ts, newest)) {
          newest = row.ts;
        }
      }
      const bootstrapTs = newest != null ? newest : new Date().toISOString();
      writeJsonAtomic(CURSOR, { last_ts: bootstrapTs });
      outcome = 'bootstrap';
      exitCode = 0;
      audit({
        ts: new Date().toISOString(),
        msg_count: 0,
        prompt_chars: 0,
        exit_code: 0,
        elapsed_ms: Date.now() - holdStartedAt,
        reply_chars: 0,
        outcome: 'bootstrap',
        acked: false,
      });
      return;
    }

    // Cursor kept in memory across rounds: we are the sole writer under the lock; mid-loop file re-read would only race our own advance.
    const cursor = readJson(CURSOR, { last_ts: null });
    let lastTs = cursor && Object.prototype.hasOwnProperty.call(cursor, 'last_ts') ? cursor.last_ts : null;

    // Loop-while-pending: mid-run inbox appends (M2 while M1 runs) must be drained before releaseLock, or tg-watch never re-fires.
    let rounds = 0;
    while (++rounds <= MAX_ROUNDS) {
      let pending = selectPending(lastTs);
      if (!pending.length) break;

      round = rounds;
      const roundStartedAt = Date.now();
      msgCount = 0;
      promptChars = 0;
      replyChars = 0;
      outcome = 'error';
      exitCode = null;
      acked = false;

      let skippedOlder = 0;
      if (pending.length > MAX_MSGS_PER_RUN) {
        skippedOlder = pending.length - MAX_MSGS_PER_RUN;
        pending = pending.slice(-MAX_MSGS_PER_RUN);
      }

      if (!CLAUDE_BIN) {
        outcome = 'error';
        const searched = describeClaudeSearch();
        replyChars = enqueueReply(
          `Claude CLI could not be found. Set CLAUDE_BIN to the absolute path of the executable, or ensure ${
            process.platform === 'win32' ? 'claude.exe' : 'claude'
          } is on PATH. Locations searched: ${searched}`,
        );
        softFail('tg-agent-claude-bin', new Error('claude CLI not found'));
        audit({
          ts: new Date().toISOString(),
          msg_count: pending.length,
          prompt_chars: 0,
          exit_code: null,
          elapsed_ms: Date.now() - roundStartedAt,
          reply_chars: replyChars,
          outcome: 'error',
          acked: false,
          round,
        });
        process.exitCode = 1;
        return;
      }

      msgCount = pending.length;
      const prompt = buildPrompt(pending, skippedOlder);
      promptChars = prompt.length;

      // Advance BEFORE the agent runs — duplicate actions are worse than a missed tick
      const advanceTs = pending[pending.length - 1].ts;
      writeJsonAtomic(CURSOR, { last_ts: advanceTs });
      lastTs = advanceTs;

      const result = await runClaude(prompt);
      exitCode = result.exitCode;
      const elapsedMs = result.elapsedMs;
      acked = !!result.acked;

      const writeAudit = () => {
        audit({
          ts: new Date().toISOString(),
          msg_count: msgCount,
          prompt_chars: promptChars,
          exit_code: exitCode,
          elapsed_ms: elapsedMs,
          reply_chars: replyChars,
          outcome,
          acked,
          round,
        });
      };

      if (result.timedOut) {
        outcome = 'timeout';
        const secs = Math.max(1, Math.round(elapsedMs / 1000));
        replyChars = enqueueReply(
          `Timed out after ${secs}s — the agent did not finish within the ${Math.round(AGENT_WALL_MS / 1000)}s wall. I stopped the run. Send the request again if you still need it.`,
        );
        writeAudit();
        continue;
      }

      if (result.spawnError) {
        outcome = 'error';
        replyChars = enqueueReply(
          `Agent failed to start: ${result.spawnError.message || result.spawnError}`,
        );
        softFail('tg-agent-spawn', result.spawnError);
        writeAudit();
        continue;
      }

      const text = String(result.stdout || '').trim();
      if (!text) {
        const sig = result.signal || null;
        const code = result.exitCode;
        const cleanExit = sig === null && code === 0;
        const tail = stderrTail(result.stderr, 300);

        if (cleanExit) {
          // Claude exited 0 but produced no output — rare and honest. One calm line, never the robotic
          // "Agent returned nothing" (which read to the operator as a fault when it was just an empty completion).
          outcome = 'empty';
          replyChars = enqueueReply(
            "The agent finished but didn't return a reply — that's unusual. Send the request again and I'll retry it.",
          );
          writeAudit();
          continue;
        }

        // Non-clean exit with empty stdout = the run FAILED or was KILLED, not "returned nothing".
        // A killed/taken-over agent (external SIGKILL, taskkill, or an operator takeover) lands EXACTLY
        // here — this branch is what spammed the operator 5× with "Agent returned nothing (empty stdout, no stderr)."
        //
        // TAKEOVER CHECK FIRST — before looking at stderr. If the operator set the pause file and killed
        // the agent, they own the reply, so stay SILENT no matter what the kill left on stderr. Checking
        // `tail` first re-fired the exact spam whenever a takeover-kill produced stderr. (bugbot MAJOR, 2026-07-15.)
        if (fs.existsSync(path.join(MEMORY, 'tg-agent.pause'))) {
          outcome = 'interrupted';
          softFail(
            'tg-agent-interrupted-paused',
            new Error(`run killed during takeover (exit=${code} signal=${sig})`),
          );
          writeAudit();
          continue;
        }

        if (tail) {
          // Real error output (and NOT a takeover) — surface it once, framed as the failure it is.
          outcome = 'exit-error';
          replyChars = enqueueReply(
            `Agent run failed (exit ${code == null ? 'killed' : code}).\n\nstderr (last ~300 chars):\n${tail}`,
          );
          writeAudit();
          continue;
        }

        // Killed/interrupted, no stderr, no takeover → ONE calm honest line, never the generic spam.
        outcome = 'interrupted';
        replyChars = enqueueReply(
          "The last run didn't finish — it exited without output. Send it again if you still need it.",
        );
        writeAudit();
        continue;
      }

      outcome = 'ok';
      replyChars = enqueueReply(text);
      writeAudit();
    }

    if (rounds > MAX_ROUNDS) {
      const still = selectPending(lastTs);
      if (still.length) {
        replyChars = enqueueReply(
          `Backlog still pending after ${MAX_ROUNDS} rounds — send anything to re-trigger, or it resumes on your next message.`,
        );
        audit({
          ts: new Date().toISOString(),
          msg_count: still.length,
          prompt_chars: 0,
          exit_code: null,
          elapsed_ms: Date.now() - holdStartedAt,
          reply_chars: replyChars,
          outcome: 'rounds-exhausted',
          acked: false,
          round: MAX_ROUNDS,
        });
      }
    }
  } catch (e) {
    outcome = 'error';
    softFail('tg-agent', e);
    try {
      replyChars = enqueueReply(`Agent run failed: ${e && e.message ? e.message : String(e)}`);
    } catch (e2) {
      softFail('tg-agent-reply', e2);
      throw e;
    }
    audit({
      ts: new Date().toISOString(),
      msg_count: msgCount,
      prompt_chars: promptChars,
      exit_code: exitCode,
      elapsed_ms: Date.now() - holdStartedAt,
      reply_chars: replyChars,
      outcome,
      acked,
      ...(round > 0 ? { round } : {}),
    });
  } finally {
    releaseLock();
  }
}

main().catch((e) => {
  softFail('tg-agent-fatal', e);
  try {
    enqueueReply(`Agent fatal error: ${e && e.message ? e.message : String(e)}`);
  } catch (e2) {
    softFail('tg-agent-fatal-reply', e2);
  }
  try {
    releaseLock();
  } catch (e3) {
    softFail('tg-agent-fatal-unlock', e3);
  }
  // Fail loud — full error, not just message
  console.error(e);
  process.exitCode = 1;
});

#!/usr/bin/env node
'use strict';

/**
 * tg-selftest.cjs — provable Telegram channel checks (anti-"green dashboard").
 *
 * A bot cannot receive its own messages via getUpdates. Inbound therefore cannot
 * be proven on demand; this tool never fabricates inbox rows to fake a round-trip.
 *
 * Exit 0 ONLY when every PROVABLE check (1–4) passes.
 * Checks 5–6 are honest reports and never decide pass/fail.
 */

const fs = require('fs');
const path = require('path');
const { Bot } = require('grammy');

const paths = null;

const ROOT = __dirname;
const MEMORY = path.join(ROOT, 'memory');

const ENV_PATH = path.join(ROOT, '.env');
const INBOX = path.join(MEMORY, 'inbox.jsonl');
const CHANNEL = path.join(MEMORY, 'telegram-channel.json');
const HEARTBEAT = path.join(MEMORY, 'tg-daemon-heartbeat.json');
const AGENT_LOG = path.join(MEMORY, 'tg-agent-log.jsonl');
const SOFT_FAIL = path.join(MEMORY, 'soft-failures.jsonl');

const TOKEN_RE = /^\d{6,12}:[A-Za-z0-9_-]{30,}$/;
const HEARTBEAT_MAX_AGE_S = 120;

function loadEnvFile(envPath) {
  const map = {};
  if (!fs.existsSync(envPath)) return map;
  const text = fs.readFileSync(envPath, 'utf8');
  for (const line of text.split(/\r?\n/)) {
    if (!line || line.trim().startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq < 0) continue;
    const key = line.slice(0, eq).trim();
    let val = line.slice(eq + 1);
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }
    map[key] = val;
  }
  return map;
}

function softFail(where, err, extra) {
  try {
    fs.mkdirSync(path.dirname(SOFT_FAIL), { recursive: true });
    const row = {
      ts: new Date().toISOString(),
      where,
      error: err && err.message ? err.message : String(err),
      ...(extra || {}),
    };
    fs.appendFileSync(SOFT_FAIL, JSON.stringify(row) + '\n', 'utf8');
  } catch (e) {
    console.error('[tg-selftest] soft-fail write failed:', e.message);
  }
}

function redactToken(token) {
  if (!token || typeof token !== 'string') return '(none)';
  const i = token.indexOf(':');
  if (i < 0) return '***';
  return `${token.slice(0, Math.min(i, 9))}:AA…`;
}

function readJsonSafe(filePath) {
  try {
    if (!fs.existsSync(filePath)) return null;
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    softFail('tg-selftest/readJson', err, { file: filePath });
    return null;
  }
}

/** Read a JSONL file as an array of row objects (whole-file, row-based — never byte-slice). */
function readJsonlRows(filePath) {
  if (!fs.existsSync(filePath)) return [];
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    softFail('tg-selftest/readJsonl', err, { file: filePath });
    return [];
  }
  const rows = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    try {
      rows.push(JSON.parse(line));
    } catch (err) {
      softFail('tg-selftest/jsonlParse', err, { file: filePath });
    }
  }
  return rows;
}

function parseTsMs(ts) {
  if (ts == null) return NaN;
  if (typeof ts === 'number' && Number.isFinite(ts)) {
    return ts < 1e12 ? ts * 1000 : ts;
  }
  if (typeof ts === 'string') {
    const ms = Date.parse(ts);
    return Number.isFinite(ms) ? ms : NaN;
  }
  return NaN;
}

function ageSeconds(ts) {
  const ms = parseTsMs(ts);
  if (!Number.isFinite(ms)) return null;
  return Math.max(0, Math.floor((Date.now() - ms) / 1000));
}

function formatAge(ageS) {
  if (ageS == null) return '(unknown age — unparseable ts)';
  return `${ageS}s ago`;
}

async function main() {
  fs.mkdirSync(MEMORY, { recursive: true });

  const results = {
    tokenConnectivity: null,
    outbound: null,
    daemonLiveness: null,
    noStackedPollers: null,
  };

  const envMap = loadEnvFile(ENV_PATH);
  const channel = readJsonSafe(CHANNEL);
  const token =
    process.env.TELEGRAM_BOT_TOKEN || envMap.TELEGRAM_BOT_TOKEN || '';
  let chatId =
    process.env.TELEGRAM_CHAT_ID || envMap.TELEGRAM_CHAT_ID || '';
  if (!chatId && channel && channel.chat_id != null) {
    chatId = String(channel.chat_id);
  }

  console.log('=== tg-selftest — provable checks only ===');
  console.log(`Token: ${redactToken(token)}`);
  console.log(`Chat:  ${chatId || '(missing)'}`);
  console.log('');

  // ── 1. TOKEN + CONNECTIVITY ──────────────────────────────────────────
  console.log('--- 1. TOKEN + CONNECTIVITY ---');
  if (!TOKEN_RE.test(token)) {
    console.error('FAIL: no valid TELEGRAM_BOT_TOKEN. Run tg-setup first.');
    console.error(`Evidence: token=${redactToken(token)} (does not match expected shape)`);
    softFail('tg-selftest/token', new Error('invalid or missing TELEGRAM_BOT_TOKEN'), {
      token: redactToken(token),
    });
    process.exit(1);
  }
  if (!chatId) {
    console.error('FAIL: no TELEGRAM_CHAT_ID. Run tg-setup first.');
    console.error('Evidence: TELEGRAM_CHAT_ID unset and telegram-channel.json has no chat_id');
    softFail('tg-selftest/chatId', new Error('missing TELEGRAM_CHAT_ID'));
    process.exit(1);
  }

  const bot = new Bot(token);
  let me;
  try {
    me = await bot.api.getMe();
  } catch (err) {
    softFail('tg-selftest/getMe', err, { token: redactToken(token) });
    console.error('FAIL: getMe rejected token');
    console.error(`Evidence: ${err && err.message ? err.message : String(err)}`);
    process.exit(1);
  }
  if (!me || me.id == null) {
    softFail('tg-selftest/getMe', new Error('getMe returned no id'));
    console.error('FAIL: getMe returned no bot id');
    process.exit(1);
  }
  console.log(`PASS: getMe ok`);
  console.log(`Evidence: bot=@${me.username || '(no username)'} id=${me.id}`);
  results.tokenConnectivity = {
    ok: true,
    evidence: `@${me.username || '?'} id=${me.id}`,
  };
  console.log('');

  // ── 2. OUTBOUND (provable) ───────────────────────────────────────────
  console.log('--- 2. OUTBOUND (provable) ---');
  let sent;
  try {
    sent = await bot.api.sendMessage(
      Number(chatId),
      `[tg-selftest] outbound probe ${new Date().toISOString()}\n(Bot cannot echo itself — inbound is reported separately, not faked.)`
    );
  } catch (err) {
    softFail('tg-selftest/sendMessage', err, { chatId: String(chatId) });
    console.error('FAIL: sendMessage rejected');
    console.error(`Evidence: ${err && err.message ? err.message : String(err)}`);
    process.exit(1);
  }
  if (!sent || sent.message_id == null) {
    softFail('tg-selftest/sendMessage', new Error('sendMessage returned no message_id'));
    console.error('FAIL: sendMessage returned no message_id');
    console.error(`Evidence: response=${JSON.stringify(sent)}`);
    process.exit(1);
  }
  console.log('PASS: Telegram accepted outbound message');
  console.log(`Evidence: message_id=${sent.message_id} chat_id=${sent.chat && sent.chat.id != null ? sent.chat.id : chatId}`);
  results.outbound = {
    ok: true,
    evidence: `message_id=${sent.message_id}`,
  };
  console.log('');

  // ── 3. DAEMON LIVENESS (provable) ────────────────────────────────────
  console.log('--- 3. DAEMON LIVENESS (provable) ---');
  const hb = readJsonSafe(HEARTBEAT);
  if (!hb) {
    softFail('tg-selftest/heartbeat', new Error('missing or unreadable heartbeat'), {
      file: HEARTBEAT,
    });
    console.error('FAIL: daemon heartbeat missing or unreadable');
    console.error(`Evidence: expected file ${HEARTBEAT}`);
    process.exit(1);
  }
  const connected = hb.connected === true;
  const ageS = ageSeconds(hb.ts);
  if (!connected) {
    softFail('tg-selftest/heartbeat', new Error('daemon not connected'), {
      connected: hb.connected,
      ts: hb.ts,
    });
    console.error('FAIL: daemon heartbeat connected !== true');
    console.error(`Evidence: connected=${JSON.stringify(hb.connected)} ts=${JSON.stringify(hb.ts)} age=${formatAge(ageS)}`);
    process.exit(1);
  }
  if (ageS == null) {
    softFail('tg-selftest/heartbeat', new Error('heartbeat ts unparseable'), {
      ts: hb.ts,
    });
    console.error('FAIL: daemon heartbeat ts unparseable');
    console.error(`Evidence: ts=${JSON.stringify(hb.ts)}`);
    process.exit(1);
  }
  if (ageS > HEARTBEAT_MAX_AGE_S) {
    softFail('tg-selftest/heartbeat', new Error('daemon heartbeat stale'), {
      ageS,
      maxAgeS: HEARTBEAT_MAX_AGE_S,
      ts: hb.ts,
    });
    console.error(`FAIL: daemon heartbeat stale (>${HEARTBEAT_MAX_AGE_S}s)`);
    console.error(`Evidence: ts=${hb.ts} age=${ageS}s (max ${HEARTBEAT_MAX_AGE_S}s)`);
    process.exit(1);
  }
  console.log('PASS: daemon heartbeat fresh and connected');
  console.log(`Evidence: connected=true ts=${hb.ts} age=${ageS}s (max ${HEARTBEAT_MAX_AGE_S}s)`);
  results.daemonLiveness = {
    ok: true,
    evidence: `connected=true age=${ageS}s`,
  };
  console.log('');

  // ── 4. NO STACKED POLLERS (provable) ─────────────────────────────────
  console.log('--- 4. NO STACKED POLLERS (provable) ---');
  let wh;
  try {
    wh = await bot.api.getWebhookInfo();
  } catch (err) {
    softFail('tg-selftest/getWebhookInfo', err);
    console.error('FAIL: getWebhookInfo rejected');
    console.error(`Evidence: ${err && err.message ? err.message : String(err)}`);
    process.exit(1);
  }
  const webhookUrl = wh && typeof wh.url === 'string' ? wh.url : '';
  const pending = wh && wh.pending_update_count != null ? wh.pending_update_count : '(unknown)';
  if (webhookUrl !== '') {
    softFail('tg-selftest/getWebhookInfo', new Error('webhook url set — starves getUpdates'), {
      url: webhookUrl,
      pending_update_count: pending,
    });
    console.error('FAIL: webhook URL is set (starves long-polling getUpdates)');
    console.error(`Evidence: url=${webhookUrl} pending_update_count=${pending}`);
    process.exit(1);
  }
  console.log('PASS: no webhook registered (getUpdates path clear)');
  console.log(`Evidence: url="" (empty) pending_update_count=${pending}`);
  results.noStackedPollers = {
    ok: true,
    evidence: `url="" pending_update_count=${pending}`,
  };
  console.log('');

  // ── 5. INBOUND (NOT provable on demand — report only) ────────────────
  console.log('--- 5. INBOUND (UNPROVABLE ON DEMAND — report only) ---');
  console.log(
    'Limit: a Telegram bot cannot receive its own messages; getUpdates only delivers user→bot traffic.'
  );
  console.log('This check NEVER writes to the inbox and NEVER fabricates evidence.');
  const inboxRows = readJsonlRows(INBOX);
  const realInbound = inboxRows.filter((r) => {
    if (!r || typeof r !== 'object') return false;
    if (r.channel !== 'telegram') return false;
    if (r.selftest === true) return false;
    if (r.from === 'tg-selftest') return false;
    return true;
  });
  const count = realInbound.length;
  let newest = null;
  let newestAge = null;
  for (const row of realInbound) {
    const ms = parseTsMs(row.ts);
    if (!Number.isFinite(ms)) continue;
    if (!newest || ms > parseTsMs(newest.ts)) {
      newest = row;
      newestAge = ageSeconds(row.ts);
    }
  }
  if (count === 0) {
    console.log('Report: real telegram inbound rows = 0');
    console.log(
      'INBOUND PATH UNPROVEN — no non-selftest telegram rows have ever been recorded.'
    );
    console.log(
      'Only way to prove inbound: the operator must message the bot; the daemon appends a real inbox row.'
    );
  } else {
    console.log(`Report: real telegram inbound rows = ${count}`);
    console.log(
      `Evidence: newest ts=${newest && newest.ts != null ? newest.ts : '(none)'} age=${formatAge(newestAge)}` +
        (newest && newest.from != null ? ` from=${newest.from}` : '')
    );
  }
  console.log('(Does not affect exit code — known limit, honestly reported.)');
  console.log('');

  // ── 6. AGENT LANE (report only) ──────────────────────────────────────
  console.log('--- 6. AGENT LANE (report only) ---');
  const agentRows = readJsonlRows(AGENT_LOG);
  if (agentRows.length === 0) {
    console.log('Report: agent has never run (tg-agent-log.jsonl empty or missing).');
  } else {
    let latest = null;
    let latestMs = -Infinity;
    for (const row of agentRows) {
      if (!row || typeof row !== 'object') continue;
      const ms = parseTsMs(row.ts);
      if (!Number.isFinite(ms)) continue;
      if (ms >= latestMs) {
        latestMs = ms;
        latest = row;
      }
    }
    if (!latest) {
      latest = agentRows[agentRows.length - 1];
    }
    const outcome = latest && latest.outcome != null ? latest.outcome : '(no outcome field)';
    const agentAge = latest ? ageSeconds(latest.ts) : null;
    console.log(`Report: newest agent outcome=${JSON.stringify(outcome)} age=${formatAge(agentAge)}`);
    if (latest && latest.ts != null) {
      console.log(`Evidence: ts=${latest.ts}`);
    }
    if (outcome === 'error') {
      const softRows = readJsonlRows(SOFT_FAIL);
      let match = null;
      for (let i = softRows.length - 1; i >= 0; i--) {
        const s = softRows[i];
        if (!s || typeof s !== 'object') continue;
        const where = typeof s.where === 'string' ? s.where : '';
        if (where.includes('tg-agent') || where.includes('agent')) {
          match = s;
          break;
        }
      }
      if (match) {
        console.log(
          `Matching soft-failure: where=${match.where} error=${match.error || '(none)'}` +
            (match.ts ? ` ts=${match.ts}` : '')
        );
      } else {
        console.log('No matching soft-failure reason found in soft-failures.jsonl.');
      }
    }
  }
  console.log('(Does not affect exit code.)');
  console.log('');

  // ── SUMMARY ──────────────────────────────────────────────────────────
  console.log('========== SUMMARY ==========');
  console.log('PASSED (provable):');
  console.log(`  1. TOKEN+CONNECTIVITY — ${results.tokenConnectivity.evidence}`);
  console.log(`  2. OUTBOUND           — ${results.outbound.evidence}`);
  console.log(`  3. DAEMON LIVENESS    — ${results.daemonLiveness.evidence}`);
  console.log(`  4. NO STACKED POLLERS — ${results.noStackedPollers.evidence}`);
  console.log('UNPROVABLE-BY-DESIGN (reported, not scored):');
  console.log(
    '  5. INBOUND — bot cannot receive its own messages; only a human (the operator) messaging the bot proves getUpdates→inbox.'
  );
  console.log(
    '  6. AGENT LANE — observational; last outcome reported above, never used to fake a channel pass.'
  );
  console.log('Exit 0: all provable checks (1–4) passed. No inbox writes. No fabricated echo.');
  process.exit(0);
}

main().catch((err) => {
  softFail('tg-selftest/main', err);
  console.error('FATAL:', err && err.stack ? err.stack : err);
  process.exit(1);
});
